"<script>\n"
"const $=id=>document.getElementById(id);const f=(n,d=1)=>Number(n).toFixed(d);\n"
"const S=[['loss','Packet loss','%',0,30,.5],['reorder','Reordering','%',0,30,.5],['dup','Duplication','%',0,30,.5],['corrupt','Corruption','%',0,10,.5],['delay','One-way delay',' ms',0,300,1],['jitter','Jitter',' ms',0,50,1],['rate','Bottleneck rate (0 = none)',' Mbps',0,100,1],['queue','Bottleneck queue',' pkts',5,200,5]];\n"
"const S2=[['size','File size',' MB',.2,20,.2,2],['slow','Receiver reads at (0 = unlimited)',' KB/s',0,5000,100,0]];\n"
"const val={};let runs=[],cur=null,prog=1,cc='reno',tlp=1,rack=1,fec=0,tcpMb={},live=null;\n"
"function mk(box,defs){defs.forEach(([k,l,u,mn,mx,st,d])=>{val[k]=d||0;const e=document.createElement('div');e.className='sl';e.innerHTML=`<label for=\"s_${k}\">${l}</label><output id=\"o_${k}\"></output><input id=\"s_${k}\" type=\"range\" min=\"${mn}\" max=\"${mx}\" step=\"${st}\" value=\"${val[k]}\">`;box.appendChild(e);const i=e.querySelector('input'),o=e.querySelector('output');const up=()=>{val[k]=+i.value;o.textContent=i.value+u};i.oninput=()=>{up();document.querySelectorAll('#presets .chip').forEach(c=>c.classList.remove('on'))};up()})}\n"
"function setv(k,v){val[k]=v;const i=$('s_'+k);i.value=v;i.dispatchEvent(new Event('input'))}\n"
"mk($('sliders'),S);mk($('sliders2'),S2);\n"
"fetch('/api/presets').then(r=>r.json()).then(ps=>{ps.forEach((p,n)=>{const b=document.createElement('button');b.className='chip';b.textContent=p.name;b.onclick=()=>{S.forEach(([k])=>setv(k,p[k]||0));if(!p.queue)setv('queue',100);document.querySelectorAll('#presets .chip').forEach(c=>c.classList.remove('on'));b.classList.add('on')};$('presets').appendChild(b);if(n==0)b.click()})});\n"
"document.querySelectorAll('#cc [data-v]').forEach(b=>b.onclick=()=>{cc=b.dataset.v;document.querySelectorAll('#cc [data-v]').forEach(x=>x.classList.toggle('on',x===b))});\n"
"$('tlp').onclick=()=>{tlp=1-tlp;$('tlp').classList.toggle('on',!!tlp)};\n"
"$('rack').onclick=()=>{rack=1-rack;$('rack').classList.toggle('on',!!rack)};\n"
"document.querySelectorAll('#fec [data-v]').forEach(b=>b.onclick=()=>{fec=+b.dataset.v;document.querySelectorAll('#fec [data-v]').forEach(x=>x.classList.toggle('on',x===b))});\n"
"function label(r){return r.impair==='none'?'clean link':r.impair.replace(/_ms/g,'ms').replace(/_mbps/g,'Mbps')}\n"
"function cfgl(r){return r.cc+' · '+(r.rack&&r.tlp?'RACK+TLP':r.rack?'RACK':r.tlp?'TLP':'classic')+(r.fec?' · FEC '+(r.fec<0?'auto':'1/'+r.fec):'')}\n"
"const sleep=ms=>new Promise(r=>setTimeout(r,ms));\n"
"async function exec(extra){\n"
" const q=new URLSearchParams({...val,cc,tlp,rack,fec,...(extra||{})});\n"
" const s=await (await fetch('/api/start?'+q)).json();if(!s.started)throw new Error('another run is in progress');\n"
" live={trace:[],events:[],size:val.size*1e6,live:true,impair:''};cur=live;prog=1;let from=0,d;\n"
" for(;;){d=await (await fetch('/api/poll?from='+from)).json();from=d.n;d.pts.forEach(p=>live.trace.push(p));\n"
"  const v=$('verdict');v.className='run';v.innerHTML=`<strong>RUNNING…</strong><span>${Math.round(d.frac*100)}% · ${f(d.mbps,0)} Mbps · ${live.trace.length} samples</span>`;draw();\n"
"  if(d.state==2)break;await sleep(70)}\n"
" const r=d.result;r.show=false;r.id=runs.length+1;r.liveN=live.trace.length;runs.push(r);cur=r;live=null;$('report').disabled=false;show(r);\n"
" if(!tcpMb[val.size]){fetch('/api/tcp?size='+val.size).then(x=>x.json()).then(t=>{tcpMb[val.size]=t.mbps;note()})}else note();\n"
" if(r.liveN<12){prog=0;play()}else{prog=1;draw()}return r}\n"
"function busy(on){['run','abcc','abrec','hrun'].forEach(i=>$(i).disabled=on);$('run').textContent=on?'RUNNING…':'RUN TRANSFER';$('busy').classList.toggle('on',on)}\n"
"async function guard(fn){busy(true);try{await fn()}catch(e){$('verdict').className='bad';$('verdict').innerHTML='<strong>ERROR</strong><span>'+e+'</span>'}busy(false)}\n"
"$('run').onclick=()=>guard(()=>exec());\n"
"$('abcc').onclick=()=>guard(async()=>{const a=await exec({cc:'reno'}),b=await exec({cc:'cubic'});a.show=b.show=true;hist();draw()});\n"
"$('abrec').onclick=()=>guard(async()=>{const a=await exec({rack:0,tlp:0,minrto:100}),b=await exec({rack:1,tlp:1,minrto:0});a.show=b.show=true;hist();draw();\n"
" $('tcpnote').textContent=`Classic recovery: ${f(a.mbps,1)} Mbps, ${a.cli.rto} timeouts.  Modern recovery (RACK + tail-loss probes + 20 ms RTO floor): ${f(b.mbps,1)} Mbps, ${b.cli.rto} timeouts.  (${f(b.mbps/Math.max(a.mbps,.01),1)}x)`});\n"
"addEventListener('keydown',e=>{if(e.key==='r'&&!e.ctrlKey&&!e.metaKey&&!$('run').disabled)$('run').click()});\n"
"function note(){const t=cur&&tcpMb[cur.size/1e6];if(!t)return;$('tcpnote').textContent=cur.impair==='none'?`Native kernel TCP on this machine, same clean link: ${f(t,0)} Mbps. This engine reached ${f(100*cur.mbps/t,0)}% of that.`:`Reference only: native kernel TCP on a clean link here does ${f(t,0)} Mbps. This run had an impaired network, so it is not a like-for-like comparison.`}\n"
"function show(r){const v=$('verdict'),ok=r.ok;v.className=ok?'ok':'bad';\n"
" v.innerHTML=ok?`<strong>✓ DELIVERED INTACT</strong><span>sent = received · SHA-256 ${r.sha.slice(0,24)}…</span>`:`<strong>✗ DELIVERY FAILED</strong><span>${r.err||'hash mismatch'}</span>`;\n"
" const c=r.cli,s=r.srv;\n"
" $('stats').innerHTML=[['Throughput',f(r.mbps,1),'Mbps'],['Transfer time',f(r.duration,2),'seconds'],['Retransmits',c.retx,`${c.fast} fast · ${c.rto} RTO · ${c.tlp} probe · ${c.rack} RACK`],['Out of order',s.ooo,`${s.dup} duplicates discarded`],['Corrupt rejected',c.bad+s.bad,'failed checksum'],['Smoothed RTT',f(c.srtt_ms,1),'ms · RTO '+f(c.rto_ms,0)+' ms']].map(x=>`<div class=\"cell\"><small>${x[0]}</small><b>${x[1]}</b><br><i>${x[2]}</i></div>`).join('');\n"
" const p=r.proxy;$('net').innerHTML=!p?'<div class=\"empty\">Clean link: the proxy was bypassed, so no packets were harmed.</div>':\n"
" `<table><tr><th>direction</th><th>packets seen</th><th>lost</th><th>queue drops</th><th>duplicated</th><th>reordered</th><th>corrupted</th></tr>`+[['client → server',p.fwd],['server → client (ACKs)',p.rev]].map(([n,d])=>`<tr><td>${n}</td><td>${d.rx}</td><td>${d.lost}</td><td>${d.qdrop}</td><td>${d.dup}</td><td>${d.reorder}</td><td>${d.corrupt}</td></tr>`).join('')+'</table>'+(c.spurious?`<div class=\"note\">${c.spurious} retransmit${c.spurious>1?'s were':' was'} detected as unnecessary (the original arrived late) and the reordering tolerance was widened.</div>`:'')+(c.probes?`<div class=\"note\">Flow control: the receiver closed its window and the sender sent ${c.probes} zero-window probes while waiting.</div>`:'');\n"
" hist();drawMap(r);renderDiag(r);draw()}\n"
"function drawMap(r){const cv=$('mapcv'),m=r.map||'',n=m.length,bx=$('mapbox');\n"
" if(!n){bx.innerHTML='<div class=\"empty\">no data segments</div>';cv.height=0;return}\n"
" let rep=0,mul=0;for(const ch of m){if(ch!=='0')rep++;if(ch>'1')mul++}\n"
" bx.innerHTML=`<div class=\"note\">${rep} of ${r.segments} packets (${f(100*rep/r.segments,1)}%) needed at least one retransmission${mul?`, ${mul} needed two or more`:''}. Each square is one packet in send order: <span style=\"color:var(--cell)\">■</span> delivered first time · <span style=\"color:var(--sig)\">■</span> repaired once · <span style=\"color:var(--bad)\">■</span> twice · <span style=\"color:var(--deep)\">■</span> 3+</div>`;\n"
" const d=devicePixelRatio||1,w=cv.clientWidth-28,c=7,g=2,cols=Math.max(1,Math.floor(w/(c+g))),rows=Math.ceil(n/cols);\n"
" cv.width=(w+28)*d;cv.height=(rows*(c+g)+12)*d;cv.style.height=(rows*(c+g)+12)+'px';const x=cv.getContext('2d');x.scale(d,d);const st=getComputedStyle(document.documentElement),C=k=>st.getPropertyValue(k).trim();\n"
" const col=['--cell','--sig','--bad','--deep'];for(let i=0;i<n;i++){x.fillStyle=C(col[Math.min(3,+m[i])]);x.fillRect(14+(i%cols)*(c+g),6+Math.floor(i/cols)*(c+g),c,c)}}\n"
"function hist(){$('hist').innerHTML='<tr><th>#</th><th>network</th><th>config</th><th>Mbps</th><th>retx</th><th>RTO</th><th>ok</th><th>overlay</th></tr>'+runs.slice().reverse().map(r=>`<tr class=\"${r===cur?'cur':''}\"><td>${r.id}</td><td style=\"text-align:left;cursor:pointer\" onclick=\"pick(${r.id})\">${label(r)}</td><td>${cfgl(r)}</td><td>${f(r.mbps,1)}</td><td>${r.cli.retx}</td><td>${r.cli.rto}</td><td style=\"color:var(--${r.ok?'ok':'bad'})\">${r.ok?'✓':'✗'}</td><td><input type=\"checkbox\" ${r.show?'checked':''} onchange=\"runs[${r.id-1}].show=this.checked;draw()\"></td></tr>`).join('')}\n"
"function renderDiag(r){const c=r.cli,s=r.srv,p=r.proxy,L=[],pc=(a,b)=>b?f(100*a/b,1)+'%':'0%';\n"
" L.push(r.ok?`All <b>${f(r.size/1e6,1)} MB</b> arrived intact: the SHA-256 fingerprints of the sent and received data match.`:`<b>The data did not arrive intact</b> (${r.err||'fingerprint mismatch'}).`);\n"
" if(p){const lost=p.fwd.lost+p.rev.lost,seen=p.fwd.rx+p.rev.rx,b=[`destroyed <b>${lost}</b> of ${seen} packets (${pc(lost,seen)})`];\n"
"  const qd=p.fwd.qdrop+p.rev.qdrop,du=p.fwd.dup+p.rev.dup,re=p.fwd.reorder+p.rev.reorder,co=p.fwd.corrupt+p.rev.corrupt;\n"
"  if(qd)b.push(`dropped ${qd} because the bottleneck queue was full`);if(du)b.push(`duplicated ${du}`);if(re)b.push(`delayed ${re} so they arrived out of order`);if(co)b.push(`damaged ${co}`);\n"
"  L.push('The network '+b.join(', ')+'.')}else L.push('The link was clean: no packet was harmed.');\n"
" L.push(c.retx?`<b>${c.retx}</b> packets (${pc(c.retx,c.sent)} of everything sent) had to be sent again: ${c.fast} noticed through repeated receipts, ${c.rack} through RACK's timing rule, ${c.tlp} through tail-loss probes and ${c.rto} only after a timeout.${c.rto?'':' No timeouts were needed.'}`:'Nothing had to be sent again.');\n"
" if(c.fec_sent)L.push(`Forward error correction sent ${c.fec_sent} parity packets (${pc(c.fec_sent,c.sent)} overhead). The receiver rebuilt <b>${s.fec_rec}</b> lost packets by itself, saving a full round trip for each.${r.fec<0?' Adaptive setting at the end: '+(c.fec_k?'1 parity per '+c.fec_k+' packets.':'off.'):''}`);\n"
" else if(r.fec<0)L.push('Adaptive FEC stayed off: the link looked clean, so it added no overhead.');\n"
" const m=/rate_mbps=([\\d.]+)/.exec(r.impair);if(m)L.push(`The sender used <b>${f(100*r.mbps/+m[1],0)}%</b> of the ${m[1]} Mbps bottleneck${p&&p.fwd.qdrop?'; each time the queue overflowed it slowed down, which is the saw-tooth in the graph':''}.`);\n"
" if(c.spurious)L.push(`${c.spurious} re-sends turned out to be unnecessary (the original packet was only late), so the engine widened its reordering tolerance.`);\n"
" if(c.probes)L.push(`The receiver closed its window ${c.probes} times; the sender waited with zero-window probes (flow control).`);\n"
" $('diag').innerHTML=L.map(x=>'<li>'+x+'</li>').join('');$('diagcard').style.display=''}\n"
"$('hrun').onclick=()=>guard(async()=>{$('hres').innerHTML='<div class=\"empty\">running both experiments…</div>';$('hcv').style.display='none';\n"
" const q=new URLSearchParams({...val,cc,tlp,rack,fec,streams:$('hs').value,per:$('hp').value});renderHol(await (await fetch('/api/hol?'+q)).json())});\n"
"function renderHol(h){const o=h.ordered,m=h.multi,row=(n,a,b)=>`<tr><td>${n}</td><td>${a}</td><td>${b}</td></tr>`;\n"
" $('hres').innerHTML=`<table><tr><th></th><th>one ordered stream (TCP-like)</th><th>independent streams</th></tr>`+row('data intact (SHA-256 per stream)',o.ok?'✓':'✗',m.ok?'✓':'✗')+row('everything finished after',f(o.duration,2)+' s',f(m.duration,2)+' s')+row('average data held back',f(o.avg,1)+' KB',f(m.avg,1)+' KB')+row('peak data held back',f(o.peak,1)+' KB',f(m.peak,1)+' KB')+row('share of time something was held back',Math.round(o.frac*100)+' %',Math.round(m.frac*100)+' %')+'</table>'\n"
" +`<div class=\"note\">${m.avg>0&&o.avg>0?`Independent streams held back <b>${f(o.avg/m.avg,1)}x less data</b>. `:''}\"Held back\" means bytes that already arrived but could not be handed to the application yet because something earlier was missing. With one ordered stream, one lost packet blocks everything behind it; with independent streams it blocks only the stream it belonged to. Total time is similar because loss repair still works per connection: the gain is that unaffected streams keep flowing.</div>`;drawHol(h)}\n"
"function drawHol(h){const cv=$('hcv');cv.style.display='block';const d=devicePixelRatio||1,w=cv.clientWidth,ht=230;cv.width=w*d;cv.height=ht*d;const g=cv.getContext('2d');g.scale(d,d);\n"
" const st=getComputedStyle(document.documentElement),C=k=>st.getPropertyValue(k).trim();g.font='11px '+C('--mono');\n"
" const L=46,R=12,T=14,B=26,pw=w-L-R,ph=ht-T-B,A=h.ordered.tl,Bm=h.multi.tl;let tm=0,ym=1;[A,Bm].forEach(a=>a.forEach(p=>{tm=Math.max(tm,p[0]);ym=Math.max(ym,p[1])}));ym*=1.1;tm=tm||1;\n"
" const X=t=>L+t/tm*pw,Y=v=>T+ph-v/ym*ph;g.strokeStyle=C('--rule');g.fillStyle=C('--mute');g.textAlign='right';\n"
" for(let i=0;i<=4;i++){const v=ym*i/4;g.beginPath();g.moveTo(L,Y(v));g.lineTo(L+pw,Y(v));g.stroke();g.fillText(f(v,0)+' KB',L-6,Y(v)+4)}\n"
" g.textAlign='center';for(let i=0;i<=5;i++){const t=tm*i/5;g.fillText(f(t,1)+'s',X(t),ht-8)}g.strokeStyle=C('--ink');g.strokeRect(L,T,pw,ph);\n"
" const ln=(a,col,fill)=>{g.beginPath();g.strokeStyle=col;g.lineWidth=1.8;a.forEach((p,i)=>i?g.lineTo(X(p[0]),Y(p[1])):g.moveTo(X(p[0]),Y(p[1])));g.stroke()};\n"
" ln(A,C('--sig'));ln(Bm,C('--cwnd'));g.textAlign='left';g.fillStyle=C('--sig');g.fillText('— one ordered stream: data held back waiting for a lost packet',L+8,T+14);g.fillStyle=C('--cwnd');g.fillText('— independent streams',L+8,T+30)}\n"
"function dl(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}\n"
"function esc(x){return String(x==null?'':x).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\n"
"function reportHtml(r){\n"
" const c=r.cli,s=r.srv,p=r.proxy,stamp=new Date().toLocaleString(),safeName=`udp-tcp-run-${r.id}-report.html`;\n"
" const stat=(k,v,u='')=>`<div class=\"metric\"><small>${esc(k)}</small><strong>${esc(v)}</strong><span>${esc(u)}</span></div>`;\n"
" const proxyRows=p?[['Client → server',p.fwd],['Server → client (ACKs)',p.rev]].map(([n,d])=>`<tr><td>${n}</td><td>${d.rx}</td><td>${d.lost}</td><td>${d.qdrop}</td><td>${d.dup}</td><td>${d.reorder}</td><td>${d.corrupt}</td></tr>`).join(''):'<tr><td colspan=\"7\">Clean link — impairment proxy was bypassed.</td></tr>';\n"
" const trace=r.trace||[],maxT=Math.max(0.001,...trace.map(x=>x[0])),maxC=Math.max(1,...trace.map(x=>x[1]));\n"
" const pts=trace.map(x=>`${(34+x[0]/maxT*700).toFixed(1)},${(190-x[1]/maxC*160).toFixed(1)}`).join(' ');\n"
" const traceRows=trace.filter((_,i)=>i===0||i===trace.length-1||i%Math.max(1,Math.ceil(trace.length/24))===0).map(x=>`<tr><td>${f(x[0],3)}</td><td>${f(x[1],0)}</td><td>${f(x[2],0)}</td><td>${f(x[3],0)}</td><td>${f(x[4],2)}</td></tr>`).join('');\n"
" const retxPct=c.sent?f(100*c.retx/c.sent,2)+'%':'0%';\n"
" const fec=r.fec<0?'Adaptive':r.fec?`1 parity / ${r.fec} packets`:'Off';\n"
" return `<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>UDP→TCP · Run ${r.id} report</title><style>\n"
" :root{--ink:#172b36;--muted:#637579;--line:#dce2d9;--paper:#fffefa;--bg:#f1f0e9;--teal:#167c80;--lime:#d8f06a;--ok:#247b56;--bad:#c4473c}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.6 Inter,system-ui,Segoe UI,sans-serif}.page{max-width:1040px;margin:36px auto;padding:0 22px 50px}.mast{background:var(--ink);color:#fff;padding:28px 32px;border-radius:14px}.eyebrow,small,.mono{font-family:Consolas,monospace;letter-spacing:.08em;text-transform:uppercase}.eyebrow{font-size:10px;color:var(--lime)}h1{font-size:34px;letter-spacing:-.05em;margin:7px 0}p{color:var(--muted)}.mast p{color:#c4d0cc;margin:0}.status{display:inline-block;margin-top:17px;padding:5px 10px;border-radius:4px;background:${r.ok?'#dff1e6':'#fbe4df'};color:${r.ok?'#17623f':'#9d3028'};font:700 11px Consolas,monospace}.meta{margin-top:10px;color:#c4d0cc;font:11px Consolas,monospace}.section{background:var(--paper);border:1px solid var(--line);border-radius:12px;margin-top:16px;padding:22px}.section h2{font:700 12px Consolas,monospace;text-transform:uppercase;letter-spacing:.1em;margin:0 0 16px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{padding:14px;background:#f5f6ef;border:1px solid var(--line);border-radius:8px;min-width:0}.metric small{display:block;color:var(--muted);font-size:9px}.metric strong{display:block;font:700 23px Consolas,monospace;overflow-wrap:anywhere}.metric span{font:10px Consolas,monospace;color:var(--muted)}table{width:100%;border-collapse:collapse;font:11px Consolas,monospace}th,td{text-align:right;padding:9px 10px;border-bottom:1px solid #e9ece5}th:first-child,td:first-child{text-align:left}th{font-size:9px;color:var(--muted);text-transform:uppercase;background:#f5f6ef}.config{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.config div{padding:10px 12px;border:1px solid var(--line);border-radius:7px}.config small{display:block;color:var(--muted);font-size:9px}.config b{font:12px Consolas,monospace;overflow-wrap:anywhere}.chart{width:100%;height:auto;background:#fbfcf8;border:1px solid var(--line);border-radius:8px}.hash{overflow-wrap:anywhere;font:11px Consolas,monospace;background:#f5f6ef;padding:12px;border-radius:7px}.foot{font:10px Consolas,monospace;color:var(--muted);text-align:center;margin-top:20px}@media(max-width:650px){.metrics{grid-template-columns:repeat(2,1fr)}.config{grid-template-columns:1fr}.mast{padding:22px}.section{padding:16px}.page{margin:16px auto}}\n"
" </style></head><body><main class=\"page\"><header class=\"mast\"><div class=\"eyebrow\">FIELD SYSTEMS / TRANSPORT LAB</div><h1>Transfer run report</h1><p>UDP→TCP · Reliable transport over UDP</p><div class=\"status\">${r.ok?'✓ DELIVERY VERIFIED':'✕ DELIVERY NOT VERIFIED'}</div><div class=\"meta\">RUN #${r.id} · GENERATED ${esc(stamp)} · LATEST COMPLETED TRANSFER</div></header>\n"
" <section class=\"section\"><h2>01 / Performance summary</h2><div class=\"metrics\">${stat('Throughput',f(r.mbps,2),'Mbps')}${stat('Transfer duration',f(r.duration,3),'seconds')}${stat('Data size',f(r.size/1e6,2),'MB')}${stat('Retransmissions',c.retx,retxPct+' of sent packets')}${stat('Smoothed RTT',f(c.srtt_ms,2),'ms')}${stat('Final congestion window',c.cwnd,'packets')}</div></section>\n"
" <section class=\"section\"><h2>02 / Experiment configuration</h2><div class=\"config\"><div><small>Network conditions</small><b>${esc(r.impair||'Not recorded')}</b></div><div><small>Congestion control</small><b>${esc(r.cc).toUpperCase()}</b></div><div><small>Loss recovery</small><b>${r.rack?'RACK':'No RACK'} · ${r.tlp?'TLP enabled':'TLP disabled'}</b></div><div><small>Forward error correction</small><b>${esc(fec)}</b></div><div><small>Minimum RTO</small><b>${f(r.minrto,0)} ms</b></div><div><small>Handshake time</small><b>${f(r.handshake_ms,3)} ms</b></div></div></section>\n"
" <section class=\"section\"><h2>03 / Reliability and packet recovery</h2><div class=\"metrics\">${stat('Packets sent',c.sent)}${stat('Packets received',c.recv)}${stat('Fast retransmits',c.fast)}${stat('RTO timeouts',c.rto)}${stat('RACK retransmits',c.rack)}${stat('Tail-loss probes',c.tlp)}${stat('Spurious retransmits',c.spurious)}${stat('FEC parity sent',c.fec_sent)}${stat('FEC packets recovered',s.fec_rec)}</div><p>Packet repair map: ${r.segments} data segments recorded; ${esc((r.map||'').split('').filter(x=>x!=='0').length)} segments required at least one retransmission.</p><div class=\"hash\"><b>Sent SHA-256</b><br>${esc(r.want)}<br><br><b>Received SHA-256</b><br>${esc(r.sha)}<br><br><b>Integrity</b>: ${r.ok&&r.sha===r.want?'MATCH':'MISMATCH / TRANSFER FAILED'}</div></section>\n"
" <section class=\"section\"><h2>04 / Network impairment</h2><table><thead><tr><th>Direction</th><th>Seen</th><th>Lost</th><th>Queue drops</th><th>Duplicated</th><th>Reordered</th><th>Corrupted</th></tr></thead><tbody>${proxyRows}</tbody></table></section>\n"
" <section class=\"section\"><h2>05 / Congestion window timeline</h2>${trace.length?`<svg class=\"chart\" viewBox=\"0 0 760 220\" role=\"img\" aria-label=\"Congestion window samples over time\"><path d=\"M34 20V190H734\" fill=\"none\" stroke=\"#879598\"/><polyline points=\"${pts}\" fill=\"none\" stroke=\"#167c80\" stroke-width=\"2.5\" stroke-linejoin=\"round\" stroke-linecap=\"round\"/><text x=\"34\" y=\"210\" fill=\"#637579\" font-size=\"10\">0 s</text><text x=\"734\" y=\"210\" text-anchor=\"end\" fill=\"#637579\" font-size=\"10\">${f(maxT,2)} s</text><text x=\"42\" y=\"14\" fill=\"#637579\" font-size=\"10\">CWND · PACKETS</text></svg>`:'<p>No congestion-window samples were recorded for this transfer.</p>'}<p>Selected trace samples</p><table><thead><tr><th>Time (s)</th><th>CWND</th><th>SSTHRESH</th><th>In flight</th><th>Smoothed RTT (ms)</th></tr></thead><tbody>${traceRows||'<tr><td colspan=\"5\">No trace samples.</td></tr>'}</tbody></table></section>\n"
" <div class=\"foot\">Generated locally by the UDP→TCP Transport Lab dashboard · Values describe this run only.</div></main></body></html>`;\n"
"}\n"
"$('report').onclick=()=>{const latest=runs[runs.length-1];if(!latest)return;dl(new Blob([reportHtml(latest)],{type:'text/html;charset=utf-8'}),`udp-tcp-run-${latest.id}-report.html`)};\n"
"$('exppng').onclick=()=>$('cv').toBlob(b=>dl(b,'cwnd.png'));\n"
"$('expcsv').onclick=()=>{if(!cur||!cur.trace.length)return;dl(new Blob(['t,cwnd,ssthresh,flight,srtt_ms\\n'+cur.trace.map(p=>p.slice(0,5).join(',')).join('\\n')],{type:'text/csv'}),'cwnd.csv')};\n"
"function pick(i){cur=runs[i-1];show(cur);note();prog=1;draw()}\n"
"let raf;function play(){cancelAnimationFrame(raf);const t0=performance.now(),D=3200;const st=n=>{prog=Math.min(1,(n-t0)/D);draw();if(prog<1)raf=requestAnimationFrame(st)};raf=requestAnimationFrame(st)}\n"
"$('replay').onclick=()=>{if(cur){prog=0;play()}};\n"
"const OV=['#9c6b00','#2b8a3e','#495057','#a61e4d'];\n"
"function draw(){const cv=$('cv'),d=devicePixelRatio||1,w=cv.clientWidth,h=340;cv.width=w*d;cv.height=h*d;const g=cv.getContext('2d');g.scale(d,d);\n"
" const st=getComputedStyle(document.documentElement),C=n=>st.getPropertyValue(n).trim();g.font='11px '+C('--mono');\n"
" const L=46,R=12,T=12,B=28,pw=w-L-R,ph=h-T-B,sh=runs.filter(r=>r.show||r===cur);if(live&&!sh.includes(live))sh.push(live);\n"
" if(!sh.length||!cur||!cur.trace.length){g.fillStyle=C('--mute');g.textAlign='center';g.fillText('run a transfer to see the congestion window',w/2,h/2);return}\n"
" let tm=0,ym=0;sh.forEach(r=>r.trace.forEach(p=>{tm=Math.max(tm,p[0]);ym=Math.max(ym,p[1]/1400,p[3]/1400)}));ym=(ym*1.1)||1;tm=tm||1;\n"
" const X=t=>L+t/tm*pw,Y=v=>T+ph-v/ym*ph;\n"
" g.strokeStyle=C('--rule');g.fillStyle=C('--mute');g.lineWidth=1;g.textAlign='right';\n"
" const ys=Math.pow(10,Math.floor(Math.log10(ym/4)))*([1,2,5,10].find(m=>ym/(Math.pow(10,Math.floor(Math.log10(ym/4)))*m)<=6)||10);\n"
" for(let v=0;v<=ym;v+=ys){g.beginPath();g.moveTo(L,Y(v));g.lineTo(L+pw,Y(v));g.stroke();g.fillText(f(v,0),L-6,Y(v)+4)}\n"
" g.textAlign='center';const xs=tm/6;for(let i=0;i<=6;i++){const t=i*xs;g.fillText(f(t,tm<3?2:1)+'s',X(t),h-10)}\n"
" g.strokeStyle=C('--ink');g.strokeRect(L,T,pw,ph);\n"
" const line=(r,k,col,wd,dash,lim)=>{g.beginPath();g.strokeStyle=col;g.lineWidth=wd;g.setLineDash(dash||[]);let on=0;r.trace.forEach(p=>{if(p[0]>lim)return;let v=p[k];if(k==2&&(v<=0||v>1e8)){on=0;return}const x=X(p[0]),y=Y(v/1400);on?g.lineTo(x,y):g.moveTo(x,y);on=1});g.stroke();g.setLineDash([])};\n"
" sh.forEach((r,i)=>{if(r!==cur)line(r,1,OV[i%4],1.5,[],1e9)});\n"
" const lim=prog*tm;line(cur,3,C('--grey'),1,[],lim);line(cur,2,C('--sig'),1.5,[5,4],lim);line(cur,1,C('--cwnd'),2.2,[],lim);\n"
" cur.events.forEach(([t,k])=>{if(t>lim)return;const x=X(t),col=k==1?C('--bad'):k==2?C('--grey'):C('--sig');g.strokeStyle=col;g.globalAlpha=.25;g.lineWidth=1;g.beginPath();g.moveTo(x,T);g.lineTo(x,T+ph);g.stroke();g.globalAlpha=1;g.fillStyle=col;g.beginPath();g.moveTo(x,T+ph-1);g.lineTo(x-4,T+ph+7);g.lineTo(x+4,T+ph+7);g.fill()});\n"
" if(prog<1){g.strokeStyle=C('--ink');g.lineWidth=1;g.beginPath();g.moveTo(X(lim),T);g.lineTo(X(lim),T+ph);g.stroke()}}\n"
"addEventListener('resize',()=>{if(cur){draw();if(cur.map)drawMap(cur)}});\n"
"</script></body></html>\n"
;
